target.css:
:root {
  --ink: #193b3d;
  --muted: #66807c;
  --paper: #fffdf7;
  --line: #d7e5dc;
  --aqua: #00a99d;
  --aqua-pale: #d9f4ed;
  --lime: #b8df4b;
  --amber: #f3b640;
  --coral: #ee6a5c;
  --deep-aqua: #175257;
}

* {
  box-sizing: border-box;
}

.nutrient-panel {
  width: 500px;
  height: 280px;
  padding: 14px;
  display: grid;
  grid-template-rows: auto 1fr auto;
  gap: 10px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
  color: var(--ink);
}

.panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.panel-title {
  display: grid;
  gap: 2px;
}

.eyebrow,
.section-label {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
}

.panel-title h1 {
  margin: 0;
  font-size: 21px;
  line-height: 1;
  letter-spacing: -0.5px;
}

.system-status {
  padding: 6px 9px;
  border-radius: 999px;
  background: var(--aqua-pale);
  color: var(--deep-aqua);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.7px;
}

.panel-grid {
  display: grid;
  grid-template-columns: 0.92fr 1.08fr;
  gap: 10px;
  min-height: 0;
}

.reservoir,
.channels {
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 12px;
}

.reservoir {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  background: var(--aqua-pale);
}

.readout {
  display: flex;
  align-items: baseline;
  gap: 7px;
}

.readout strong {
  font-size: 30px;
  line-height: 1;
  letter-spacing: -1.5px;
}

.readout span {
  color: var(--deep-aqua);
  font-size: 11px;
  font-weight: 700;
}

.level-track {
  height: 9px;
  overflow: hidden;
  border-radius: 999px;
  background: var(--paper);
}

.level-fill {
  display: block;
  width: 62%;
  height: 100%;
  border-radius: inherit;
  background: var(--aqua);
}

.reservoir-details {
  margin: 0;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 5px;
}

.reservoir-details div {
  padding-top: 6px;
  border-top: 1px solid var(--aqua);
}

.reservoir-details dt {
  color: var(--muted);
  font-size: 9px;
  font-weight: 700;
}

.reservoir-details dd {
  margin: 2px 0 0;
  font-size: 12px;
  font-weight: 800;
}

.channels {
  display: flex;
  flex-direction: column;
  gap: 9px;
  background: var(--paper);
}

.channel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.channel-head h2 {
  margin: 0;
  font-size: 13px;
  line-height: 1;
}

.next-dose {
  padding: 4px 6px;
  border-radius: 5px;
  background: var(--coral);
  color: var(--paper);
  font-size: 9px;
  font-weight: 800;
}

.dose-list {
  margin: 0;
  padding: 0;
  display: grid;
  gap: 5px;
  list-style: none;
}

.dose-list li {
  display: grid;
  grid-template-columns: 10px 1fr auto;
  align-items: center;
  gap: 7px;
  min-height: 27px;
  padding: 5px 7px;
  border: 1px solid var(--line);
  border-radius: 7px;
  font-size: 11px;
}

.dose-list strong {
  font-weight: 750;
}

.dose-list li > span:last-child {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
}

.dose-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

.dose-dot.aqua {
  background: var(--aqua);
}

.dose-dot.lime {
  background: var(--lime);
}

.dose-dot.amber {
  background: var(--amber);
}

.panel-footer {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 650;
}

.footer-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--aqua);
}

